"""Small HTTP client for the order service: token refresh, rate-limit waits, retries, full logging."""
import datetime
import email.utils
import json
import os
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


class Unexpected(Exception):
    pass


class Client:
    def __init__(self, data_dir, max_attempts=40):
        self.data_dir = data_dir
        self.token = None
        self.max_attempts = max_attempts
        self.stats = {}
        self.log_fh = open(os.path.join(data_dir, "requests.log"), "a")

    def log(self, msg):
        ts = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="milliseconds")
        self.log_fh.write(f"{ts} {msg}\n")
        self.log_fh.flush()

    def bump(self, key):
        self.stats[key] = self.stats.get(key, 0) + 1

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
        except Exception as e:  # connection reset, timeout, truncated read...
            return None, {}, repr(e).encode()

    @staticmethod
    def _wait_seconds(headers, body):
        """How long the server asked us to wait, or None if it didn't say."""
        hl = {k.lower(): v for k, v in headers.items()}
        ra = hl.get("retry-after")
        if ra is not None:
            try:
                return float(ra)
            except ValueError:
                dt = email.utils.parsedate_to_datetime(ra)
                return max(0.0, (dt - datetime.datetime.now(datetime.timezone.utc)).total_seconds())
        try:
            j = json.loads(body)
        except Exception:
            return None
        if isinstance(j, dict):
            for k in ("retry_after", "retry_after_seconds", "retry_in", "wait", "wait_seconds"):
                if k in j:
                    return float(j[k])
            for k in ("retry_after_ms", "wait_ms"):
                if k in j:
                    return float(j[k]) / 1000.0
        return None

    def new_token(self):
        for attempt in range(self.max_attempts):
            st, h, b = self._raw("POST", "/token", auth=False)
            self.bump(f"token:{st}")
            if st == 200:
                try:
                    self.token = json.loads(b)["token"]
                    self.log(f"POST /token -> 200 {self.token}")
                    return
                except Exception:
                    pass
            self.log(f"POST /token -> {st} headers={h} body={b[:500]!r}")
            if st == 429:
                w = self._wait_seconds(h, b)
                if w is None:
                    raise Unexpected(f"429 on /token without a wait hint: {h} {b[:500]!r}")
                time.sleep(w)
            else:
                time.sleep(min(2 ** attempt * 0.2, 5))
        raise Unexpected("could not obtain token")

    def get_json(self, path, ok_statuses=(200,)):
        """GET an authenticated path. Returns (status, parsed_json). Retries everything transient."""
        if self.token is None:
            self.new_token()
        for attempt in range(self.max_attempts):
            st, h, b = self._raw("GET", path, auth=True)
            self.bump(f"{path.split('?')[0].split('/')[1]}:{st}")
            if st in ok_statuses:
                try:
                    return st, json.loads(b)
                except Exception as e:
                    self.log(f"GET {path} -> {st} but body not JSON ({e}): {b[:500]!r}")
                    self.bump("bad_json")
                    time.sleep(0.5)
                    continue
            self.log(f"GET {path} -> {st} headers={h} body={b[:500]!r}")
            if st == 401 or st == 403:
                self.new_token()
            elif st == 429:
                w = self._wait_seconds(h, b)
                if w is None:
                    raise Unexpected(f"429 without a wait hint: {h} {b[:500]!r}")
                time.sleep(w)
            elif st is None or st >= 500:
                time.sleep(min(2 ** attempt * 0.2, 5))
            else:
                raise Unexpected(f"GET {path} -> {st} {h} {b[:500]!r}")
        raise Unexpected(f"gave up on {path} after {self.max_attempts} attempts")

